import{_ as t,a}from"./chunks/project-2-benchmark.Bwz0ykVo.js";import{_ as o,o as r,c as s,a2 as i}from"./chunks/framework.BRXuf3UQ.js";const k=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"guide/examples.md","filePath":"guide/examples.md"}'),n={name:"guide/examples.md"};function d(c,e,l,p,h,m){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h1><p>The repository includes three complete example projects that you can run as-is.</p><p>Every invocation needs an explicit <code>--config</code>; the option has no default. Build the jar first (see <a href="./installation">Installation</a>) — <code>mvn clean package</code> produces <code>target/owlsda.jar</code>.</p><div class="warning custom-block"><p class="custom-block-title">A run overwrites the example&#39;s output</p><p>OWL-SDA deletes the file at <code>output-path</code> before it starts, and archives any previous benchmark directory. Point <code>output-path</code> somewhere else first if you want to keep what is already there.</p></div><h2 id="project-1-glass-production-facility" tabindex="-1">Project 1 - Glass Production Facility <a class="header-anchor" href="#project-1-glass-production-facility" aria-label="Permalink to &quot;Project 1 - Glass Production Facility&quot;">​</a></h2><p><code>examples/project-1/</code> demonstrates a production-process ontology with temporal variants.</p><h3 id="what-it-generates" tabindex="-1">What it generates <a class="header-anchor" href="#what-it-generates" aria-label="Permalink to &quot;What it generates&quot;">​</a></h3><p>Given the prompt:</p><blockquote><p><em>&quot;Create a data example for a glass production facility. Introduce multiple versions of the operation in different years with different systems, processes and subprocesses.&quot;</em></p></blockquote><p>OWL-SDA generates RDF instances for facilities, systems, processes, and subprocesses across multiple years, illustrated using a glass manufacturing scenario (installations like furnaces, processes such as melting/annealing, and measurement points for emissions).</p><p>The config also shows off <code>context-window-tokens</code>, an <code>openai-compatible</code> provider pointed at a self-hosted gateway, and a long list of <code>extract.mirrors</code> for external ontologies.</p><h3 id="running-the-example" tabindex="-1">Running the example <a class="header-anchor" href="#running-the-example" aria-label="Permalink to &quot;Running the example&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/owlsda.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/project-1/config.yml</span></span></code></pre></div><h3 id="key-files" tabindex="-1">Key files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key files&quot;">​</a></h3><table tabindex="0"><thead><tr><th>File</th><th>Description</th></tr></thead><tbody><tr><td><code>examples/project-1/config.yml</code></td><td>Run configuration.</td></tr><tr><td><code>examples/project-1/input.ttl</code></td><td>OWL ontology used as generation input.</td></tr><tr><td><code>examples/project-1/input-example.txt</code></td><td>Extra user context passed to the agents.</td></tr><tr><td><code>examples/project-1/reasoner.rules</code></td><td>Custom Jena rules for the <a href="./reasoner">reasoner</a>.</td></tr><tr><td><code>examples/project-1/shacl/</code></td><td>Cached SHACL shapes (<code>default-shacl.ttl</code>, <code>inferred-shacl.ttl</code>), reused across runs.</td></tr><tr><td><code>examples/project-1/benchmark_paper/</code></td><td>Curated benchmark snapshot used for the plots below.</td></tr></tbody></table><p>A run additionally writes <code>output.ttl</code> (the generated triples), <code>inferred.ttl</code> (the reasoner&#39;s inferred model), <code>external/</code> (cached external ontologies) and <code>benchmark/</code> (snapshots) into <code>examples/project-1/</code>. None of these are shipped in the repository.</p><h2 id="project-2-patient-history-record" tabindex="-1">Project 2 - Patient History Record <a class="header-anchor" href="#project-2-patient-history-record" aria-label="Permalink to &quot;Project 2 - Patient History Record&quot;">​</a></h2><p><code>examples/project-2/</code> demonstrates richer generation on a larger medical ontology input.</p><h3 id="what-it-generates-1" tabindex="-1">What it generates <a class="header-anchor" href="#what-it-generates-1" aria-label="Permalink to &quot;What it generates&quot;">​</a></h3><p>Given the prompt:</p><blockquote><p><em>&quot;Create a patient history record for the ontology.&quot;</em></p></blockquote><p>OWL-SDA generates linked patient history data aligned with the classes and properties in <code>owlapi.xrdf</code>.</p><p>This config mixes providers: <code>ollama</code> workers with a <code>copilot</code> supervisor and reviewer.</p><h3 id="running-the-example-1" tabindex="-1">Running the example <a class="header-anchor" href="#running-the-example-1" aria-label="Permalink to &quot;Running the example&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/owlsda.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/project-2/config.yml</span></span></code></pre></div><h3 id="key-files-1" tabindex="-1">Key files <a class="header-anchor" href="#key-files-1" aria-label="Permalink to &quot;Key files&quot;">​</a></h3><table tabindex="0"><thead><tr><th>File</th><th>Description</th></tr></thead><tbody><tr><td><code>examples/project-2/config.yml</code></td><td>Run configuration.</td></tr><tr><td><code>examples/project-2/owlapi.xrdf</code></td><td>Main ontology input (RDF/XML).</td></tr><tr><td><code>examples/project-2/2504.08750v1.pdf</code></td><td>Domain paper passed as user context.</td></tr><tr><td><code>examples/project-2/reasoner.rules</code></td><td>Custom Jena rules for the reasoner.</td></tr><tr><td><code>examples/project-2/shacl/</code></td><td>Cached SHACL shapes.</td></tr><tr><td><code>examples/project-2/output.ttl</code></td><td>Output kept from an earlier run, so you can inspect the result without running anything. <strong>Deleted at the start of your next run.</strong></td></tr><tr><td><code>examples/project-2/benchmark_paper/</code></td><td>Curated benchmark snapshot used for the plots below.</td></tr></tbody></table><p><code>inferred.ttl</code>, <code>external/</code> and <code>benchmark/</code> appear here after a run; they are not shipped.</p><h2 id="project-3-ldes-parking-garage-observations" tabindex="-1">Project 3 - LDES Parking Garage Observations <a class="header-anchor" href="#project-3-ldes-parking-garage-observations" aria-label="Permalink to &quot;Project 3 - LDES Parking Garage Observations&quot;">​</a></h2><blockquote><p>Work in progress - not fully benchmarked yet.</p></blockquote><p><code>examples/project-3/</code> demonstrates LDES-oriented dummy data generation for parking availability observations. It also showcases <strong>URL-based user context</strong>: the LDES specification is fetched live from the web at runtime rather than loaded from a local file.</p><h3 id="what-it-generates-2" tabindex="-1">What it generates <a class="header-anchor" href="#what-it-generates-2" aria-label="Permalink to &quot;What it generates&quot;">​</a></h3><p>Given the prompt:</p><blockquote><p><em>&quot;Generate dummy LDES data for a parking garage with observations about available spaces over time.&quot;</em></p></blockquote><p>OWL-SDA generates parking observation instances linked to a stream resource, with timestamps and availability values aligned to the ontology constraints.</p><h3 id="running-the-example-2" tabindex="-1">Running the example <a class="header-anchor" href="#running-the-example-2" aria-label="Permalink to &quot;Running the example&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/owlsda.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/project-3/config.yml</span></span></code></pre></div><h3 id="key-files-2" tabindex="-1">Key files <a class="header-anchor" href="#key-files-2" aria-label="Permalink to &quot;Key files&quot;">​</a></h3><table tabindex="0"><thead><tr><th>File</th><th>Description</th></tr></thead><tbody><tr><td><code>examples/project-3/config.yml</code></td><td>Config using both local and URL-based user context (<code>https://semiceu.github.io/LinkedDataEventStreams/</code>).</td></tr><tr><td><code>examples/project-3/input.ttl</code></td><td>Main ontology input for parking and observation terms.</td></tr><tr><td><code>examples/project-3/input-example.txt</code></td><td>Domain constraints passed as extra context.</td></tr><tr><td><code>examples/project-3/reasoner.rules</code></td><td>Empty placeholder — the reasoner runs without custom rules.</td></tr><tr><td><code>examples/project-3/shacl/</code></td><td>Empty until the first run generates and caches the shapes.</td></tr><tr><td><code>examples/project-3/output.ttl</code></td><td>Empty placeholder; filled by a run.</td></tr></tbody></table><p><code>inferred.ttl</code>, <code>external/</code> contents and <code>benchmark/</code> are likewise produced by a run.</p><h2 id="benchmark-result-images" tabindex="-1">Benchmark Result Images <a class="header-anchor" href="#benchmark-result-images" aria-label="Permalink to &quot;Benchmark Result Images&quot;">​</a></h2><p>The plots below are generated from each example&#39;s <code>benchmark-summary.json</code> with <code>scripts/plot_benchmark.py</code>.</p><p>Benchmark time is calculated as the sum of <code>durationMs</code> for all iterations <strong>except the final <code>REVIEW_*</code> iteration</strong>, because that final review snapshot is already an aggregate of the review stages.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><code>examples/project-N/benchmark_paper/</code> is a hand-curated snapshot kept for the paper. It was produced by an earlier version of OWL-SDA and uses a flat layout; a run today writes <code>live/</code> and <code>archive/&lt;timestamp&gt;/</code> under <code>benchmark.output-dir</code> instead. See <a href="./benchmarking">Benchmarking</a>.</p></div><h3 id="project-1-benchmark" tabindex="-1">Project 1 benchmark <a class="header-anchor" href="#project-1-benchmark" aria-label="Permalink to &quot;Project 1 benchmark&quot;">​</a></h3><p><strong>Glass Production Facility</strong> · 11 rounds · ~27.9 min total · 297 final triples · 0 violations at acceptance · ~2.1M tokens</p><p><img src="'+t+'" alt="Project 1 benchmark plot"></p><p><a href="/owl-sda/benchmarks/project-1-benchmark.png">PNG fallback</a></p><h3 id="project-2-benchmark" tabindex="-1">Project 2 benchmark <a class="header-anchor" href="#project-2-benchmark" aria-label="Permalink to &quot;Project 2 benchmark&quot;">​</a></h3><p><strong>Patient History Record</strong> · 22 rounds · ~54.8 min total · 2,698 final triples · 0 violations at acceptance · ~2.7M tokens</p><p><img src="'+a+'" alt="Project 2 benchmark plot"></p><p><a href="/owl-sda/benchmarks/project-2-benchmark.png">PNG fallback</a></p><h2 id="compare-the-benchmark-raw-data" tabindex="-1">Compare the benchmark raw data <a class="header-anchor" href="#compare-the-benchmark-raw-data" aria-label="Permalink to &quot;Compare the benchmark raw data&quot;">​</a></h2><ul><li><code>examples/project-1/benchmark_paper/benchmark-summary.json</code></li><li><code>examples/project-2/benchmark_paper/benchmark-summary.json</code></li><li><code>examples/project-1/benchmark_paper/benchmark_stats.txt</code></li><li><code>examples/project-2/benchmark_paper/benchmark_stats.txt</code></li></ul><p>Watch a run of your own live in the browser with <code>--web-ui</code> — see the <a href="./web-ui">Web UI</a> guide.</p>',55)])])}const b=o(n,[["render",d]]);export{k as __pageData,b as default};
